import type { ReaderEntry, WordGloss } from "@/features/spirituality/types";

type Word = Required<WordGloss>;

function verse(
  chapter: number,
  verseNumber: number,
  sequence: number,
  section: string,
  original: string,
  transliteration: string,
  meaning: string,
  words: Word[],
  note?: string
): ReaderEntry {
  return {
    id: `gita-${chapter}-${verseNumber}`,
    sequence,
    section,
    label: `${chapter}.${verseNumber}`,
    original,
    transliteration,
    meaning,
    words,
    note,
  };
}

