      { original: "गोविन्द", transliteration: "govinda", meaning: "O KRiShNa" },
      { original: "किम्", transliteration: "kim", meaning: "what" },
      { original: "भोगैः", transliteration: "bhogaiḥ", meaning: "enjoyment" },
      { original: "जीवितेन", transliteration: "jīvitena", meaning: "living" },
      { original: "वा", transliteration: "vā", meaning: "either" }
