      { original: "श्यालाः", transliteration: "śyālāḥ", meaning: "brothers-in-law" },
      { original: "सम्बन्धिनः", transliteration: "sambandhinaḥ", meaning: "relatives" },
      { original: "तथा", transliteration: "tathā", meaning: "as well as" }
