      { original: "दुष्कृताम्", transliteration: "duṣkṛtām", meaning: "of the miscreants" },
      { original: "धर्मसंस्थापनार्थाय", transliteration: "dharma-saṃsthāpana-arthāya", meaning: "for the sake of establishing dharma" },
      { original: "सम्भवामि", transliteration: "sambhavāmi", meaning: "I do incarnate" },
      { original: "युगे", transliteration: "yuge", meaning: "millennium" },
      { original: "युगे", transliteration: "yuge", meaning: "millennium" }
