      { original: "अधिदैवतम्", transliteration: "adhidaivatam", meaning: "called adhidaiva" },
      { original: "अधियज्ञः", transliteration: "adhiyajñaḥ", meaning: "the Lord of sacrifice" },
      { original: "अहम्", transliteration: "aham", meaning: "I" },
      { original: "एव", transliteration: "eva", meaning: "certainly" },
      { original: "अत्र", transliteration: "atra", meaning: "here" },
      { original: "देहे", transliteration: "dehe", meaning: "in the body" },
      { original: "देहभृताम्", transliteration: "deha-bhṛtām", meaning: "of the embodied" },
      { original: "वर", transliteration: "vara", meaning: "O best" }
