      { original: "एव", transliteration: "eva", meaning: "certainly" },
      { original: "एति", transliteration: "eti", meaning: "does attain" },
      { original: "कौन्तेय", transliteration: "kaunteya", meaning: "O son of Kunti" },
      { original: "सदा", transliteration: "sadā", meaning: "always" },
      { original: "तद्त्", transliteration: "tadt", meaning: "at that time" },
      { original: "भावभावितः", transliteration: "bhāva-bhāvitaḥ", meaning: "be + remembering" }
