      { original: "देव", transliteration: "deva", meaning: "O Lord" },
      { original: "रूपम्", transliteration: "rūpam", meaning: "whose form" },
      { original: "प्रसीद", transliteration: "prasīda", meaning: "be pleased" },
      { original: "देवेश", transliteration: "deveśa", meaning: "O Lord of all lords" },
      { original: "जगत्निवास", transliteration: "jagat-nivāsa", meaning: "the material world + abode" }
