      { original: "संन्यस्य", transliteration: "saṃnyasya", meaning: "giving up completely" },
      { original: "मत्पराः", transliteration: "mat-parāḥ", meaning: "in relationship with Me" },
      { original: "अनन्येन", transliteration: "ananyena", meaning: "without division" },
      { original: "एव", transliteration: "eva", meaning: "certainly" },
      { original: "योगेन", transliteration: "yogena", meaning: "in devotional service" },
      { original: "माम्", transliteration: "mām", meaning: "me" },
      { original: "ध्यायन्तः", transliteration: "dhyāyantaḥ", meaning: "meditating" },
      { original: "उपासते", transliteration: "upāsate", meaning: "worship" }
