      { original: "आत्मना", transliteration: "ātmanā", meaning: "by the purified mind" },
      { original: "अन्ये", transliteration: "anye", meaning: "others" },
      { original: "साङ्ख्येन", transliteration: "sāṅkhyena", meaning: "of philosophical discussion" },
      { original: "योगेन", transliteration: "yogena", meaning: "in devotional service" },
      { original: "कर्मयोगेन", transliteration: "karma-yogena", meaning: "by the linking process of devotion" },
      { original: "च", transliteration: "ca", meaning: "and" },
      { original: "अपरे", transliteration: "apare", meaning: "some others" }
