      { original: "जायते", transliteration: "jāyate", meaning: "is taking place" },
      { original: "तथा", transliteration: "tathā", meaning: "as well as" },
      { original: "प्रलीनः", transliteration: "pralīnaḥ", meaning: "being dissolved" },
      { original: "तमसि", transliteration: "tamasi", meaning: "the mode of ignorance" },
      { original: "मूढयोनिषु", transliteration: "mūḍha-yoniṣu", meaning: "in animal species" },
      { original: "जायते", transliteration: "jāyate", meaning: "is taking place" }
