      { original: "यत्", transliteration: "yat", meaning: "because" },
      { original: "गत्वा", transliteration: "gatvā", meaning: "attaining" },
      { original: "न", transliteration: "na", meaning: "nor" },
      { original: "निवर्तन्ते", transliteration: "nivartante", meaning: "come back" },
      { original: "तत्", transliteration: "tat", meaning: "that" },
      { original: "धाम", transliteration: "dhāma", meaning: "abode" },
      { original: "परमम्", transliteration: "paramam", meaning: "transcendental" },
      { original: "मम", transliteration: "mama", meaning: "my" }
