      { original: "पार्थ", transliteration: "pārtha", meaning: "O son of Pritha" },
      { original: "सम्पदम्", transliteration: "sampadam", meaning: "the qualities" },
      { original: "आसुरीम्", transliteration: "āsurīm", meaning: "atheistic" }
